// Package result is the single schema of every eval/results/*.json file.
// Results are generated by `make eval` and never edited by hand.
package result

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"time"
)

// SchemaVersion is the only version Validate accepts.
const SchemaVersion = 1

// Case results.
const (
	TP         = "tp"
	FP         = "fp"
	FN         = "fn"
	TN         = "tn"
	OutOfScope = "out_of_scope"
)

// Cell is one (endpoint, relationship) pair of the authorization matrix.
type Cell struct {
	Endpoint     string `json:"endpoint"`
	Relationship string `json:"relationship"`
}

// Case is one scored decision.
type Case struct {
	ID       string `json:"id"`
	Kind     string `json:"kind"`
	Expected []Cell `json:"expected"`
	Flagged  []Cell `json:"flagged"`
	Result   string `json:"result"`
	Reason   string `json:"reason"`
}

// App describes the system under test.
type App struct {
	ImageDigest string `json:"image_digest,omitempty"`
	Name        string `json:"name"`
	Version     string `json:"version"`
}

// Authzcov identifies the tool build that was evaluated.
type Authzcov struct {
	Commit  string `json:"commit"`
	Version string `json:"version"`
}

// MachineInfo describes where the run happened.
type MachineInfo struct {
	Arch      string `json:"arch"`
	CPUs      int    `json:"cpus"`
	GoVersion string `json:"go_version"`
	OS        string `json:"os"`
}

// Summary counts the cases. Precision is tp/(tp+fp) and recall tp/(tp+fn), rounded to 3
// decimals; nil (JSON null) when the denominator is 0.
type Summary struct {
	FN         int      `json:"fn"`
	FP         int      `json:"fp"`
	OutOfScope int      `json:"out_of_scope"`
	Precision  *float64 `json:"precision"`
	Recall     *float64 `json:"recall"`
	TN         int      `json:"tn"`
	TP         int      `json:"tp"`
}

// Result is one results file.
type Result struct {
	App           App            `json:"app"`
	Authzcov      Authzcov       `json:"authzcov"`
	Cases         []Case         `json:"cases"`
	Extra         map[string]any `json:"extra"`
	GeneratedAt   string         `json:"generated_at"`
	Machine       MachineInfo    `json:"machine"`
	SchemaVersion int            `json:"schema_version"`
	Suite         string         `json:"suite"`
	Summary       Summary        `json:"summary"`
}

// Machine reports the current machine.
func Machine() MachineInfo {
	return MachineInfo{Arch: runtime.GOARCH, CPUs: runtime.NumCPU(), GoVersion: runtime.Version(), OS: runtime.GOOS}
}

// Now is the generated_at timestamp (RFC 3339, UTC); SOURCE_DATE_EPOCH overrides the clock.
func Now() string {
	t := time.Now()
	if v := os.Getenv("SOURCE_DATE_EPOCH"); v != "" {
		if n, err := strconv.ParseInt(v, 10, 64); err == nil {
			t = time.Unix(n, 0)
		}
	}
	return t.UTC().Format(time.RFC3339)
}

// ParseVersion reads the output of `authzcov version` ("authzcov v0.1.0 (commit abc1234)").
func ParseVersion(out string) Authzcov {
	var a Authzcov
	if f := strings.Fields(out); len(f) > 1 {
		a.Version = f[1]
	}
	if i := strings.Index(out, "(commit "); i >= 0 {
		a.Commit = strings.TrimSpace(strings.TrimSuffix(strings.TrimSpace(out[i+len("(commit "):]), ")"))
	}
	return a
}

func round3(f float64) float64 { return math.Round(f*1000) / 1000 }

// Summarize counts the cases.
func Summarize(cases []Case) Summary {
	var s Summary
	for _, c := range cases {
		switch c.Result {
		case TP:
			s.TP++
		case FP:
			s.FP++
		case FN:
			s.FN++
		case TN:
			s.TN++
		case OutOfScope:
			s.OutOfScope++
		}
	}
	if d := s.TP + s.FP; d > 0 {
		p := round3(float64(s.TP) / float64(d))
		s.Precision = &p
	}
	if d := s.TP + s.FN; d > 0 {
		r := round3(float64(s.TP) / float64(d))
		s.Recall = &r
	}
	return s
}

func eqPtr(a, b *float64) bool {
	if a == nil || b == nil {
		return a == b
	}
	return *a == *b
}

// Validate checks the schema: version, required fields, known result values, unique case ids,
// and a summary that matches the cases.
func Validate(r *Result) error {
	if r == nil {
		return fmt.Errorf("result: nil")
	}
	var errs []string
	bad := func(f string, a ...any) { errs = append(errs, fmt.Sprintf(f, a...)) }
	if r.SchemaVersion != SchemaVersion {
		bad("schema_version %d, want %d", r.SchemaVersion, SchemaVersion)
	}
	for name, v := range map[string]string{"suite": r.Suite, "app.name": r.App.Name, "app.version": r.App.Version,
		"authzcov.version": r.Authzcov.Version, "machine.os": r.Machine.OS, "machine.arch": r.Machine.Arch,
		"machine.go_version": r.Machine.GoVersion} {
		if v == "" {
			bad("%s is empty", name)
		}
	}
	if r.Machine.CPUs <= 0 {
		bad("machine.cpus must be positive")
	}
	if _, err := time.Parse(time.RFC3339, r.GeneratedAt); err != nil {
		bad("generated_at: %v", err)
	}
	ids := map[string]bool{}
	for i, c := range r.Cases {
		switch c.Result {
		case TP, FP, FN, TN, OutOfScope:
		default:
			bad("case %d (%s): unknown result %q", i, c.ID, c.Result)
		}
		if c.ID == "" || c.Kind == "" || c.Reason == "" {
			bad("case %d (%s): id, kind and reason are required", i, c.ID)
		}
		if ids[c.ID] {
			bad("duplicate case id %q", c.ID)
		}
		ids[c.ID] = true
	}
	if r.Cases == nil {
		bad("cases is null")
	}
	want := Summarize(r.Cases)
	if r.Summary.TP != want.TP || r.Summary.FP != want.FP || r.Summary.FN != want.FN || r.Summary.TN != want.TN ||
		r.Summary.OutOfScope != want.OutOfScope || !eqPtr(r.Summary.Precision, want.Precision) || !eqPtr(r.Summary.Recall, want.Recall) {
		bad("summary does not match the cases")
	}
	if len(errs) > 0 {
		return fmt.Errorf("result: invalid: %s", strings.Join(errs, "; "))
	}
	return nil
}

// Write sorts the cases by id, validates, and writes path atomically (2-space indent, trailing newline).
func Write(path string, r *Result) error {
	sort.SliceStable(r.Cases, func(i, j int) bool { return r.Cases[i].ID < r.Cases[j].ID })
	for i := range r.Cases {
		if r.Cases[i].Expected == nil {
			r.Cases[i].Expected = []Cell{}
		}
		if r.Cases[i].Flagged == nil {
			r.Cases[i].Flagged = []Cell{}
		}
	}
	if r.Cases == nil {
		r.Cases = []Case{}
	}
	if r.Extra == nil {
		r.Extra = map[string]any{}
	}
	if err := Validate(r); err != nil {
		return err
	}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetIndent("", "  ")
	enc.SetEscapeHTML(false)
	if err := enc.Encode(r); err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), ".result-*.tmp")
	if err != nil {
		return err
	}
	defer func() { _ = os.Remove(tmp.Name()) }()
	if _, err := tmp.Write(buf.Bytes()); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tmp.Name(), 0o644); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), path)
}
